export const GRIB_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/grib-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getGribStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(GRIB_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
